mapper.sql:
FROM base_job_log l LEFT JOIN base_job j ON j.id = l.job_id
WHERE l.begin_time >= #{start} AND l.begin_time < #{end}
  AND (l.trigger_source IS NULL OR l.trigger_source != 3)
  AND COALESCE(l.job_type, j.job_type) = #{type}
  AND l.status = #{status}
  AND COALESCE(l.job_name, j.job_name, l.clazz_path) LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'

mapper.select:
SELECT l.id, l.job_id AS jobId, COALESCE(l.job_name, j.job_name, l.clazz_path) AS jobName,
       l.begin_time AS beginTime, l.end_time AS endTime, l.duration_ms AS durationMs,
       l.duration, l.status, COALESCE(l.job_type, j.job_type) AS jobType, j.cron
FROM base_job_log l LEFT JOIN base_job j ON j.id = l.job_id
WHERE l.begin_time < #{end}
  AND (l.begin_time >= #{start}
    OR (l.status IN (1, 3) AND #{now} > #{start})
    OR (COALESCE(l.status, 0) NOT IN (1, 3) AND l.end_time > #{start}))
  AND (l.trigger_source IS NULL OR l.trigger_source != 3)
  AND COALESCE(l.job_type, j.job_type) = #{type}
  AND l.status = #{status}
  AND COALESCE(l.job_name, j.job_name, l.clazz_path) LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'

  AND (l.job_id IS NULL OR l.job_id NOT IN
    #{id}
    OR NOT ())

ORDER BY l.begin_time, l.id

mapper.update:
UPDATE base_job_log SET dispatch_end_time = #{record.dispatchEndTime},
    dispatch_duration_ms = #{record.dispatchDurationMs}
WHERE id = #{record.id} AND status = 1 AND dispatch_end_time IS NULL
